/**
 * Merge the message's `books` into one increment per bookId, in first-appearance order.
 * Only entries the monolith's single `ADD` would have accepted survive: a `bookId` that
 * is not a non-empty string, or a `quantity` that is not a finite JS number, was rejected
 * by DynamoDB and swallowed -- so it must not change salesCount here either.
 */
function mergeQuantities(books) {
  const qtyByBook = new Map();
  for (const book of books) {
    if (!book || typeof book !== 'object') {
      continue;
    }
    const bookId = book.bookId;
    const quantity = book.quantity;
    if (typeof bookId !== 'string' || bookId.length === 0) {
      continue;
    }
    if (typeof quantity !== 'number' || !Number.isFinite(quantity)) {
      continue;
    }
    qtyByBook.set(bookId, (qtyByBook.get(bookId) || 0) + quantity);
  }
  return qtyByBook;
}

/**
 * The chunks for one message: [marker, ...effects] per chunk, each chunk with its own
 * marker so a partially committed message can be redelivered safely.
 */
function transactionChunks(orderId, qtyByBook) {
  const entries = [...qtyByBook];
  const updates = entries.map(([bookId, quantity]) => ({
    Update: {
      TableName: BESTSELLERS_TABLE,
      Key: { bookId: bookId },
      UpdateExpression: 'ADD salesCount :qty',
      ExpressionAttributeValues: { ':qty': quantity },
    },
  }));

  const chunks = [];
  for (let i = 0; i < updates.length; i += MAX_EFFECTS) {
    chunks.push(updates.slice(i, i + MAX_EFFECTS));
  }

  const expiresAt = Math.floor(Date.now() / 1000) + MARKER_TTL_SECONDS;
  return chunks.map((chunk, index) => {
    const pk = chunks.length > 1 ? `${CONSUMER}#${orderId}#${index}` : `${CONSUMER}#${orderId}`;
    const marker = {
      Put: {
        TableName: IDEMPOTENCY_TABLE,
        Item: { pk: pk, expiresAt: expiresAt },
        ConditionExpression: 'attribute_not_exists(pk)',
      },
    };
    return [marker, ...chunk]; // marker first: a duplicate shows up in CancellationReasons[0]
  });
}

